<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { supabase } from '@/lib/supabase'
import { requireUser } from '@/services/supabase-api'
import type { Database } from '@/types/database.types'
const letters=ref<Database['public']['Tables']['future_letters']['Row'][]>([]), subject=ref(''), body=ref(''), date=ref(''), error=ref(''), saving=ref(false)
async function load(){const user=await requireUser();const result=await supabase.from('future_letters').select('*').eq('user_id',user.id).order('scheduled_for');if(result.error)throw result.error;letters.value=result.data}
onMounted(()=>{void load().catch(e=>error.value=e.message)})
async function save(){error.value='';saving.value=true;try{const user=await requireUser();const scheduled=new Date(date.value);if(scheduled<=new Date())throw new Error('Choose a future date.');const result=await supabase.from('future_letters').insert({user_id:user.id,subject:subject.value,body:body.value,scheduled_for:scheduled.toISOString()});if(result.error)throw result.error;subject.value='';body.value='';date.value='';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function remove(id:string){if(!window.confirm('Delete this letter?'))return;try{const user=await requireUser();const result=await supabase.from('future_letters').delete().eq('id',id).eq('user_id',user.id).is('sent_at',null);if(result.error)throw result.error;await load()}catch(e){error.value=(e as Error).message}}
</script>
<template><main class="letters-page"><header class="letters-hero"><p class="eyebrow">FROM THE YOU OF TODAY</p><h1>Letters to tomorrow</h1><p>A few honest words can travel a long way. Write to the person you are still becoming.</p><span aria-hidden="true">✉</span></header><p v-if="error" role="alert" class="alert">{{error}}</p><div class="letters-layout"><form @submit.prevent="save" class="letter-paper"><div class="letter-topline"><span>CRONEVIA · PRIVATE CORRESPONDENCE</span><span>✳</span></div><label>A subject for this letter<input v-model="subject" required maxlength="255" placeholder="A note for another day" /></label><label>Dear future me…<textarea v-model="body" required rows="9" placeholder="What do you hope you remember? What would you like to hear?" /></label><label>Deliver it on<input v-model="date" type="datetime-local" required /><small>Your letter stays private in your account until its chosen date.</small></label><button :disabled="saving">{{saving?'Keeping your letter…':'Keep this letter'}} <span>↗</span></button></form><section class="letter-archive"><div class="archive-heading"><div><p class="eyebrow">YOUR WORDS, KEPT SAFE</p><h2>The postbox</h2></div><span>{{letters.length.toString().padStart(2,'0')}}</span></div><div v-if="!letters.length" class="letter-empty"><span>⌑</span><h3>Your postbox is quiet.</h3><p>When you write a letter to yourself, it will be waiting here for its chosen day.</p></div><article v-for="letter in letters" :key="letter.id" class="letter-item"><div class="letter-date"><span :class="{delivered:letter.sent_at}">{{letter.sent_at?'DELIVERED':'IN THE POSTBOX'}}</span><time>{{new Date(letter.scheduled_for).toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'})}}</time></div><h3>{{letter.subject}}</h3><p>{{letter.body}}</p><button v-if="!letter.sent_at" @click="remove(letter.id)">Remove this letter</button></article></section></div><p class="delivery-note">Letters are stored in your private Cronevia account. Delivery reminders depend on your account’s notification setup.</p></main></template>
<style scoped>
.letters-page{--wine:#74283c;--ink:#392d28;--muted:#827568;--line:#e6dccd;max-width:1050px;margin:auto;padding:32px 20px 75px;color:var(--ink)}.letters-hero{position:relative;padding:28px 32px 31px;border:1px solid #e4d6c1;background:linear-gradient(112deg,#f2e8d8,#fbf8f0 72%);overflow:hidden}.eyebrow{font-size:9px;letter-spacing:.18em;color:#947852}.letters-hero h1{margin:10px 0;color:var(--wine);font:clamp(36px,5vw,49px) Georgia,serif}.letters-hero>p:nth-of-type(2){max-width:540px;color:var(--muted);line-height:1.65}.letters-hero>span{position:absolute;right:9%;top:50%;transform:translateY(-50%);color:#b5a17f;font:68px Georgia,serif}.letters-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(260px,.85fr);gap:23px;margin-top:23px}.letter-paper,.letter-archive{padding:24px;background:#fcfaf5;border:1px solid var(--line);box-shadow:0 12px 35px #45321c08}.letter-topline,.archive-heading{display:flex;justify-content:space-between;align-items:center;padding-bottom:16px;border-bottom:1px solid var(--line);color:#95846b;font-size:8px;letter-spacing:.14em}.letter-paper label{display:grid;gap:7px;margin:17px 0;color:#5c4d41;font-size:12px;font-weight:600}.letter-paper input,.letter-paper textarea{width:100%;padding:12px;border:1px solid #ddd1c0;border-radius:3px;background:#fffefa;color:var(--ink);font:14px Georgia,serif}.letter-paper textarea{resize:vertical;line-height:1.8}.letter-paper small{color:var(--muted);font-weight:400}.letter-paper>button{display:flex;justify-content:space-between;align-items:center;width:100%;min-height:45px;padding:0 15px;border:0;border-radius:3px;background:var(--wine);color:#fffaf2;cursor:pointer;font-size:12px}.archive-heading .eyebrow{margin:0 0 6px}.archive-heading h2{margin:0;color:var(--wine);font:22px Georgia,serif}.archive-heading>span{font:24px Georgia,serif}.letter-item{padding:16px 2px;border-bottom:1px solid var(--line)}.letter-date{display:flex;justify-content:space-between;gap:8px;align-items:center}.letter-date span{font-size:8px;letter-spacing:.12em;color:#9a8b74}.letter-date .delivered{color:#667455}.letter-date time{font-size:10px;color:var(--muted)}.letter-item h3{margin:10px 0;color:var(--wine);font:19px Georgia,serif}.letter-item p{display:-webkit-box;overflow:hidden;-webkit-line-clamp:4;-webkit-box-orient:vertical;white-space:pre-wrap;color:#62574e;font:13px/1.65 Georgia,serif}.letter-item button{padding:0;border:0;background:none;color:var(--wine);font-size:11px;cursor:pointer}.letter-empty{padding:30px 8px;text-align:center;color:var(--muted)}.letter-empty>span{color:#a58f6d;font:34px Georgia,serif}.letter-empty h3{color:var(--wine);font:19px Georgia,serif}.letter-empty p{font-size:12px;line-height:1.6}.delivery-note{margin:16px 2px;color:var(--muted);font-size:10px;line-height:1.6}.alert{margin-top:15px;padding:12px;background:#f9e7e3;color:#842e25;font-size:13px}@media(max-width:700px){.letters-page{padding:18px 14px 50px}.letters-layout{grid-template-columns:1fr}.letter-paper,.letter-archive{padding:19px}.letters-hero{padding:23px 20px}.letters-hero>span{right:6%;font-size:48px;opacity:.55}.letters-hero>p:nth-of-type(2){max-width:75%}}
</style>